/**
 * "Zone — Midpoint" — a precise recreation of the reference Nullscapes
 * level's second background zone (`Nullscapes-level.gmd`, decoded this
 * session, not part of this app's own source), real x-range ~11,415 to
 * ~20,565 of the level's ~26,250-unit length. Confirmed as its own
 * distinct zone by two Color Trigger objects in the level data that
 * snap the sky's own base color at that exact boundary: pure black
 * (0,0,0) at x=11,415, settling to (10,20,26) at x=11,880 — both
 * instant (duration 0), reproduced below as a fast two-step color swap,
 * not a slow fade, because that is what the source data actually says.
 *
 * `ZONE_POINTS` is real extracted data — position, rotation, scale,
 * color, and per-instance opacity/blend-flag from this zone's own color
 * channels — proportionally downsampled from 22,071 real placed objects
 * (every decoration object in this x-range, trigger and
 * special-mechanism objects excluded) down to 5,208 points, kept dense
 * deliberately per instruction to prioritize fidelity over render cost.
 *
 * Five depth tiers, confirmed directly from this zone's own object data
 * (not assumed from elsewhere in the level):
 *  - FRONT terrain silhouette (object 507, z-layer 3): the dense foreground
 *    grass/spike line, gray, solid.
 *  - BACK solid framing (1753/1133/1137/694, z-layer -1): white, solid,
 *    no blending — a defined back wall/tunnel edge.
 *  - MID translucent haze (1525, z-layer 0): white at 75%/30% opacity,
 *    no blending, in a rigid, evenly-spaced repeat (0% per-instance color
 *    variation in the source data) — mechanical, not organic.
 *  - FRONT additive glow (1756/693/1888, z-layer 7-9): white, with the
 *    engine's own additive-blending flag set on their source channels —
 *    these are the only points rendered with `mixBlendMode: 'screen'`.
 *  - FRONT solid silhouette (1292, z-layer 7): flat black accent shapes.
 *
 * Every point is a plain `Animated.View` (a small rotated square), not an
 * SVG shape — `mixBlendMode` on a raw `react-native-svg` Circle/Rect
 * crashes at runtime on web (see `NullscapesBurst.tsx`'s own doc comment
 * for the exact error); Views are the proven-working technique for blend
 * mode in this app, so every tier uses the same primitive for consistency,
 * not just the blended one. The literal GD sprite art behind each object
 * id isn't recoverable from placement data alone — these are proxy shapes
 * carrying the real position/size/rotation/color/depth, not a pixel
 * reproduction of the original textures.
 *
 * Positioning is percentage-based (not SVG viewBox units), which only
 * stays pixel-aligned with the reference proportions when this component
 * is rendered at its native aspect ratio (900:260, `VIEW_W`/`VIEW_H`
 * below) — a full-bleed mount at a very different aspect ratio will
 * stretch, not letterbox. Ignoring render cost per instruction: 5,208
 * `Animated.View`s mount unconditionally, with no virtualization.
 *
 * The level's own "white circle emerging and exploding" effect sits right
 * at this zone's own start (the same x≈11,415-11,880 the Color Triggers
 * fire at) — reused here via the already-built `NullscapesBurst`
 * component rather than re-decoded, since that effect was always built to
 * match the described look, not literally decoded GD particle math.
 *
 * Draft / not wired into any screen yet — built standalone for review.
 */
import { memo, useEffect } from 'react';
import { StyleSheet, View, type ViewStyle } from 'react-native';
import Animated, {
  Easing,
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withSequence,
  withTiming,
} from 'react-native-reanimated';

import { NullscapesBurst } from './NullscapesBurst';

export const VIEW_W = 900;
