const BASE_SIZE = 2.0;
// Real normalized position of the Color-Trigger-driven sky swap / burst
// moment within this zone's own 0..VIEW_W span (computed from the real
// trigger x, not eyeballed).
const BURST_LEFT_PCT = (29.5 / VIEW_W) * 100;

function depthOpacity(z: number, baseOp: number): number {
  const depthFactor = Math.max(0.45, Math.min(1, 0.55 + (z + 3) / 14));
  return baseOp * depthFactor;
}

function NullscapesZoneMidpointImpl({ style }: { style?: ViewStyle }): React.JSX.Element {
  const reduceMotion = useReducedMotion();
  const sky = useSharedValue(0); // 0 = SKY_A, 1 = SKY_B

  useEffect(() => {
    if (reduceMotion) {
      sky.value = 1;
      return;
    }
    // Instant snap to black, then settle — matches the source data's own
    // two Color Triggers (both duration 0 in the level, eased slightly
    // here only so the settle-step reads as a transition, not a tear).
    sky.value = withSequence(withTiming(0, { duration: 1 }), withTiming(1, { duration: 450, easing: Easing.out(Easing.quad) }));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reduceMotion]);

  const skyStyle = useAnimatedStyle(() => ({ opacity: sky.value }));

  const fullBleed = StyleSheet.flatten(style)?.position === 'absolute';

  return (
    <View style={[fullBleed ? styles.fill : styles.wrap, style]} pointerEvents="none" importantForAccessibility="no-hide-descendants">
      <View style={[styles.sky, { backgroundColor: SKY_A }]} />
      <Animated.View style={[styles.sky, { backgroundColor: SKY_B }, skyStyle]} />

      {ZONE_POINTS.map((p, i) => {
        const size = BASE_SIZE * p.s;
        const leftPct = (p.x / VIEW_W) * 100;
        const topPct = (p.y / VIEW_H) * 100;
        return (
          <View
            key={i}
            style={[
              styles.point,
              {
                left: `${leftPct}%`,
                top: `${topPct}%`,
                width: size,
                height: size,
                backgroundColor: p.c,
                opacity: depthOpacity(p.z, p.op),
                transform: [{ rotate: `${p.rot}deg` }],
              },
              p.bl ? styles.screenBlend : null,
            ]}
          />
        );
      })}

      <View style={[styles.burstBox, { left: `${BURST_LEFT_PCT}%` }]}>
        <NullscapesBurst />
      </View>
    </View>
  );
}

export const NullscapesZoneMidpoint = memo(NullscapesZoneMidpointImpl);

const styles = StyleSheet.create({
  wrap: { width: '100%', aspectRatio: VIEW_W / VIEW_H, borderRadius: 4, overflow: 'hidden' },
  fill: { flex: 1 },
  sky: { ...StyleSheet.absoluteFill },
  point: { position: 'absolute' },
  screenBlend: { mixBlendMode: 'screen' },
  burstBox: { position: 'absolute', top: '4%', width: 140, height: 90 },
});
